mkdir -p /tmp/stackalloc_test && cd /tmp/stackalloc_test && dotnet new console --force -q && cat > Program.cs << 'EOF'
using System;

unsafe
{
    Span<nint> span = stackalloc nint[4];
    span[0] = 10;
    span[1] = 20;
    span[2] = 30;
    span[3] = 40;

    Console.WriteLine($"Length: {span.Length}");
    Console.WriteLine($"Element size: {sizeof(nint)} bytes");
    for (int i = 0; i < span.Length; i++)
        Console.WriteLine($"  span[{i}] = {span[i]}");
}
EOF
# Enable unsafe and set lang version
sed -i 's|</PropertyGroup>|<AllowUnsafeBlocks>true</AllowUnsafeBlocks>\n</PropertyGroup>|' stackalloc_test.csproj
dotnet run 2>&1

